update matter_codex_agent_sessions set
	status = case when $2 <> '' then $2 else status end,
	active_turn_id = null,
	active_run_id = '',
	kubernetes_namespace = '',
	pod_name = '',
	pvc_name = '',
	token_secret_ref = '',
	last_activity_at = now(),
	updated_at = now()
where session_key = $1
returning
	id,
	session_key,
	project_id,
	chat_id,
	role_id,
	session_scope,
	mattermost_channel_id,
	mattermost_root_post_id,
	codex_session_id,
	status,
	coalesce(active_turn_id, 0),
	active_run_id,
	kubernetes_namespace,
	pod_name,
	pvc_name,
	token_secret_ref,
	capabilities::text,
	session_archive_gzip_base64,
	ttl_seconds,
	last_activity_at,
	expires_at,
	created_at,
	updated_at,
	openai_account_name;
